[AttributeUsage(AttributeTargets.All, AllowMultiple = true)]
class Attr : Attribute
{
    public Attr(bool b, int i, params object?[] parameters) { }
}

[Attr(i: 1, b: true, "a")]
[Attr(i: 1, b: true, "a", "b")]
class Program { }

